-- Referee cross-market query (run read-only on Neon project Gold Control, 2026-10-13).
-- CME GLBX hourly continuous (.c.0, calendar roll => roll gaps not adjusted). Daily close = last hourly bar of NY17 session label.
-- Output per cluster: <symbol>:<% change from window onset close to cluster end close>/<% change over prior ~4 weeks to onset>.
-- Window onset = earliest start of any qualifying threshold window (see REPRODUCE.py); for same-day 4H/12H clusters baseline = previous session close.
WITH k(id,onset,e,dir) AS (VALUES ('C001','2023-01-05'::date,'2023-01-12'::date,'UP'),('C002','2023-01-27'::date,'2023-02-08'::date,'DOWN'),('C003','2023-03-06'::date,'2023-03-23'::date,'UP'),('C004','2023-04-27'::date,'2023-05-04'::date,'UP'),('C005','2023-09-22'::date,'2023-10-03'::date,'DOWN'),('C006','2023-10-06'::date,'2023-10-19'::date,'UP'),('C007','2023-11-24'::date,'2023-12-01'::date,'UP'),('C008','2023-12-04'::date,'2023-12-04'::date,'DOWN'),('C009','2023-12-01'::date,'2023-12-08'::date,'DOWN'),('C010','2023-12-12'::date,'2023-12-19'::date,'UP'),('C011','2024-02-26'::date,'2024-03-11'::date,'UP'),('C012','2024-03-22'::date,'2024-04-11'::date,'UP'),('C013','2024-04-12'::date,'2024-04-12'::date,'DOWN'),('C014','2024-04-19'::date,'2024-04-24'::date,'DOWN'),('C015','2024-05-08'::date,'2024-05-20'::date,'UP'),('C016','2024-05-17'::date,'2024-05-27'::date,'DOWN'),('C017','2024-06-06'::date,'2024-06-07'::date,'DOWN'),('C018','2024-07-09'::date,'2024-07-17'::date,'UP'),('C019','2024-07-18'::date,'2024-07-25'::date,'DOWN'),('C020','2024-07-25'::date,'2024-08-01'::date,'UP'),('C021','2024-08-06'::date,'2024-08-16'::date,'UP'),('C022','2024-09-06'::date,'2024-09-16'::date,'UP'),('C023','2024-09-17'::date,'2024-09-26'::date,'UP'),('C024','2024-10-15'::date,'2024-10-22'::date,'UP'),('C025','2024-10-30'::date,'2024-11-15'::date,'DOWN'),('C026','2024-11-14'::date,'2024-11-22'::date,'UP'),('C027','2024-11-22'::date,'2024-11-25'::date,'DOWN'),('C028','2024-12-06'::date,'2024-12-11'::date,'UP'),('C029','2024-12-11'::date,'2024-12-19'::date,'DOWN'),('C030','2025-01-29'::date,'2025-02-10'::date,'UP'),('C031','2025-03-10'::date,'2025-03-19'::date,'UP'),('C032','2025-03-24'::date,'2025-04-02'::date,'UP'),('C033','2025-03-31'::date,'2025-04-08'::date,'DOWN'),('C034','2025-04-04'::date,'2025-04-22'::date,'UP'),('C035','2025-04-23'::date,'2025-04-23'::date,'DOWN'),('C036','2025-04-24'::date,'2025-05-01'::date,'DOWN'),('C037','2025-04-29'::date,'2025-05-07'::date,'UP'),('C038','2025-05-06'::date,'2025-05-16'::date,'DOWN'),('C039','2025-05-15'::date,'2025-05-15'::date,'UP'),('C040','2025-05-14'::date,'2025-05-26'::date,'UP'),('C041','2025-06-06'::date,'2025-06-13'::date,'UP'),('C042','2025-07-15'::date,'2025-07-22'::date,'UP'),('C043','2025-07-23'::date,'2025-07-30'::date,'DOWN'),('C044','2025-07-30'::date,'2025-08-07'::date,'UP'),('C045','2025-08-25'::date,'2025-09-08'::date,'UP'),('C046','2025-09-18'::date,'2025-09-23'::date,'UP'),('C047','2025-09-24'::date,'2025-10-20'::date,'UP'),('C048','2025-10-16'::date,'2025-10-29'::date,'DOWN'),('C049','2025-11-04'::date,'2025-11-13'::date,'UP'),('C050','2025-11-12'::date,'2025-11-17'::date,'DOWN'),('C051','2025-11-21'::date,'2025-11-28'::date,'UP'),('C052','2025-12-15'::date,'2025-12-26'::date,'UP'),('C053','2025-12-23'::date,'2025-12-31'::date,'DOWN')), s(id,st) AS (VALUES ('C001','2023-01-12'::date),('C002','2023-02-03'::date),('C003','2023-03-13'::date),('C004','2023-05-04'::date),('C005','2023-09-29'::date),('C006','2023-10-13'::date),('C007','2023-12-01'::date),('C008','2023-12-04'::date),('C009','2023-12-08'::date),('C010','2023-12-19'::date),('C011','2024-03-04'::date),('C012','2024-04-01'::date),('C013','2024-04-12'::date),('C014','2024-04-24'::date),('C015','2024-05-15'::date),('C016','2024-05-23'::date),('C017','2024-06-07'::date),('C018','2024-07-16'::date),('C019','2024-07-25'::date),('C020','2024-08-01'::date),('C021','2024-08-12'::date),('C022','2024-09-13'::date),('C023','2024-09-24'::date),('C024','2024-10-22'::date),('C025','2024-11-06'::date),('C026','2024-11-20'::date),('C027','2024-11-25'::date),('C028','2024-12-11'::date),('C029','2024-12-18'::date),('C030','2025-02-05'::date),('C031','2025-03-13'::date),('C032','2025-03-31'::date),('C033','2025-04-04'::date),('C034','2025-04-09'::date),('C035','2025-04-23'::date),('C036','2025-05-01'::date),('C037','2025-05-06'::date),('C038','2025-05-12'::date),('C039','2025-05-15'::date),('C040','2025-05-21'::date),('C041','2025-06-13'::date),('C042','2025-07-22'::date),('C043','2025-07-30'::date),('C044','2025-08-04'::date),('C045','2025-09-01'::date),('C046','2025-09-23'::date),('C047','2025-10-01'::date),('C048','2025-10-17'::date),('C049','2025-11-10'::date),('C050','2025-11-14'::date),('C051','2025-11-28'::date),('C052','2025-12-22'::date),('C053','2025-12-29'::date)),
b AS (SELECT symbol, ((ts_event + interval '1 hour') AT TIME ZONE 'America/New_York' + interval '7 hours')::date AS sd, ts_event, close FROM gold_research_cme_glbx_futures_2023_2026_h1_5roots_continuous_c WHERE ts_event BETWEEN '2022-11-01' AND '2026-01-02'),
d AS (SELECT DISTINCT ON (symbol, sd) symbol, sd, close FROM b WHERE extract(isodow from sd) < 6 ORDER BY symbol, sd, ts_event DESC),
x AS (SELECT k.id, k.dir, d0.symbol,
  (SELECT close FROM d z WHERE z.symbol=d0.symbol AND (CASE WHEN k.onset=s.st THEN z.sd<k.onset ELSE z.sd<=k.onset END) ORDER BY sd DESC LIMIT 1) base,
  (SELECT close FROM d z WHERE z.symbol=d0.symbol AND z.sd<=k.e ORDER BY sd DESC LIMIT 1) fin,
  (SELECT close FROM d z WHERE z.symbol=d0.symbol AND z.sd<=k.onset - 28 ORDER BY sd DESC LIMIT 1) pre
  FROM k JOIN s USING(id) CROSS JOIN (SELECT DISTINCT symbol FROM d) d0)
SELECT id, dir, string_agg(replace(symbol,'.c.0','')||':'||round((100*(fin/base-1))::numeric,2)||'/'||coalesce(round((100*(base/pre-1))::numeric,1)::text,'na'), ' ' ORDER BY symbol) win_pct_slash_pre4w FROM x GROUP BY id, dir ORDER BY id;
